/**
 * Clothbound Web — Built-In Public Domain Sample Works
 *
 * Packaged via buildMinimalEpubBlob() from ./epub.js so clicking any classic
 * runs through the exact same client-side ZIP + EPUB 3 parser pipeline as a
 * user-dropped .epub file. Zero network fetches.
 */

import { buildMinimalEpubBlob } from "./epub.js";

function svgToDataUrl(svg) {
  return "data:image/svg+xml;charset=utf-8," + encodeURIComponent(svg.trim());
}

function escapeSvg(str) {
  return String(str || "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

function wrapTitleLines(title, maxChars = 16, maxLines = 4) {
  const words = String(title || "Untitled").split(/\s+/);
  const lines = [];
  let line = "";
  for (const w of words) {
    if (!line) {
      line = w;
    } else if ((line + " " + w).length <= maxChars) {
      line += " " + w;
    } else {
      lines.push(line);
      line = w;
      if (lines.length >= maxLines - 1) break;
    }
  }
  if (line && lines.length < maxLines) lines.push(line);
  return lines;
}

export function makeGeneratedCoverSvg(title, author, format = "epub") {
  const palettes = {
    epub: { bg: "#2B3C5E", spine: "#1F2D48", accent: "#E4B54A", ink: "#F6F0E4", sub: "#C7CEDD" },
    pdf: { bg: "#4D2C28", spine: "#391F1C", accent: "#E3B469", ink: "#F8F1E7", sub: "#D8C6BC" },
  };
  const pal = palettes[format] || palettes.epub;
  const lines = wrapTitleLines(title, 15, 4);
  const titleSvg = lines
    .map(
      (ln, idx) =>
        `<text x="152" y="${136 + idx * 31}" text-anchor="middle" fill="${pal.ink}" font-family="Literata, Georgia, serif" font-size="23" font-weight="500">${escapeSvg(ln)}</text>`
    )
    .join("");

  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 280 420" width="280" height="420">
  <rect width="280" height="420" fill="${pal.bg}"/>
  <rect x="0" y="0" width="24" height="420" fill="${pal.spine}"/>
  <line x1="25" y1="0" x2="25" y2="420" stroke="#ffffff" stroke-opacity="0.14" stroke-width="1"/>
  <rect x="40" y="24" width="218" height="372" rx="4" fill="none" stroke="${pal.accent}" stroke-opacity="0.46" stroke-width="1.5"/>
  <rect x="48" y="32" width="202" height="356" rx="2" fill="none" stroke="${pal.accent}" stroke-opacity="0.22" stroke-width="1"/>
  <text x="152" y="72" text-anchor="middle" fill="${pal.accent}" font-family="Inter, sans-serif" font-size="10" font-weight="600" letter-spacing="2.4">${escapeSvg(format.toUpperCase())}</text>
  ${titleSvg}
  <line x1="112" y1="278" x2="192" y2="278" stroke="${pal.accent}" stroke-opacity="0.65" stroke-width="1.2"/>
  <text x="152" y="314" text-anchor="middle" fill="${pal.sub}" font-family="Inter, sans-serif" font-size="12" font-weight="500">${escapeSvg(String(author || "").slice(0, 26))}</text>
  <text x="152" y="366" text-anchor="middle" fill="${pal.accent}" fill-opacity="0.7" font-family="Inter, sans-serif" font-size="9" letter-spacing="2">CLOTHBOUND LOCAL</text>
</svg>`;
}

export function makeGeneratedCoverDataUrl(title, author, format = "epub") {
  return svgToDataUrl(makeGeneratedCoverSvg(title, author, format));
}

