export function getSampleWork(sampleId) {
  return SAMPLE_WORKS.find((w) => w.id === sampleId) || null;
}

export function buildSampleEpubBlob(work) {
  return buildMinimalEpubBlob({
    id: `urn:clothbound:sample:${work.id}`,
    title: work.title,
    author: work.author,
    language: "en",
    description: work.description,
    date: work.year,
    publisher: "Clothbound Public Domain Editions",
    coverSvg: work.coverSvg,
    chapters: work.chapters,
  });
}
